function out = exp_stage4a6_parameter_domain_diagnostic(cfg,sc)
%EXP_STAGE4A6_PARAMETER_DOMAIN_DIAGNOSTIC Orthogonal topology/domain audit.
    if nargin<1||isempty(cfg),root=fileparts(fileparts(mfilename('fullpath')));cfg=default_config(root);end
    if nargin<2||isempty(sc),sc=stage4a6_parameter_domain_config(cfg,'formal');end
    ensure_result_dirs(cfg);tall=tic;root=cfg.root_dir;source_hash=stage4a6_source_tree_hash(root);bank=generate_stage4a6_trial_bank(sc,'all');base=generate_radial_topology_candidates(sc.generator);theta_grid=topology_parameter_grid(sc.parameter_search);[hash,canonical]=stage4a4_scientific_config_hash(struct('stage',sc.stage_name,'version',sc.version,'source_tree_hash',source_hash,'generator',sc.generator,'parameter_search',sc.parameter_search,'grids',sc.grids,'seeds',struct('development',sc.development_seeds,'final',sc.final_seeds),'sample_design',sc.sample_design,'etas',sc.extended_domain_eta_candidates,'optimization',sc.optimization,'calibration',sc.parameter_calibration));
    decisions=struct([]);labels=struct([]);profiles=struct([]);selection=struct([]);thresholds=struct([]);identrows=struct([]);runtimes=struct([]);
    for gi=1:numel(sc.grids)
        grid=sc.grids(gi);fprintf('Stage 4A.6 grid %s (%d points)\n',grid.id,numel(grid.frequency_hz));obs=make_observations(bank,grid.frequency_hz,cfg,sc.measurement_kind);
        [cache,audit]=load_a5_cache(cfg,sc,grid,base,theta_grid);[sub8,~]=stage4a5_make_subbands(grid.frequency_hz,8,grid.id,hash);[mask_design,~]=build_frozen_resampling_masks(grid,unique({bank.replicate_id},'stable'),sc,hash);spec=m3_spec(sc,grid.id);raw=cell(numel(bank),1);
        for i=1:numel(bank),md=mask_design(strcmp({mask_design.replicate_id},bank(i).replicate_id));raw{i}=score_stage4a5_1_observation(obs{i},cache,sub8,md.masks,struct('candidate_count_before_prior',7));raw{i}.sample_id=bank(i).sample_id;raw{i}.replicate_id=bank(i).replicate_id;raw{i}.split=bank(i).split;end
        dev_eta_rows=struct([]);
        for eta=sc.extended_domain_eta_candidates
            domain=build_extended_parameter_domain(sc.parameter_search,eta);
            for ri=1:numel(sc.development_seeds)
                rep=sprintf('dev%02d',ri);cal=find(strcmp({bank.replicate_id},rep)&strcmp({bank.split},'stage4a6_calibration'));val=find(strcmp({bank.replicate_id},rep)&strcmp({bank.split},'stage4a6_validation'));tm=calibrate_stage4a5_confirmation([raw{cal}],sc,grid.id,hash,sc.development_seeds(ri));td=apply_topology(raw,tm,spec,grid.id);
                ev=profile_indices([cal val],td([cal val]),obs,raw,cache,base,grid,cfg,domain,sc);pm=calibrate_parameter_domain_detector(flatten(ev(1:numel(cal))),sc,eta,hash);
                for q=1:numel(val),joint=apply_joint_topology_parameter_decision(td(numel(cal)+q),ev{numel(cal)+q},pm,'A6_M3_joint_diagnostic');z=eta_row();z.eta=eta;z.grid_id=grid.id;z.parameter_domain_truth=bank(val(q)).parameter_domain_truth;z.parameter_status=joint.parameter_domain_status;dev_eta_rows=append(dev_eta_rows,z);end
            end
        end
        selection_source='development validation only';if isempty(sc.development_seeds),selected_eta=0.5;selection_source='frozen from Stage 4A.6 development run';else,selected_eta=select_stage4a6_eta(dev_eta_rows,sc.extended_domain_eta_candidates,0.10);end;selection=append(selection,struct('grid_id',grid.id,'selected_eta',selected_eta,'selection_source',selection_source,'experiment_scientific_hash',hash));fprintf('  frozen eta = %.3g\n',selected_eta);domain=build_extended_parameter_domain(sc.parameter_search,selected_eta);
        if strcmp(sc.mode,'development'),continue;end
        for ri=1:numel(sc.final_seeds)
            rep=sprintf('final%02d',ri);cal=find(strcmp({bank.replicate_id},rep)&strcmp({bank.split},'stage4a6_final_calibration'));test=find(strcmp({bank.replicate_id},rep)&strcmp({bank.split},'stage4a6_final_test'));tm=calibrate_stage4a5_confirmation([raw{cal}],sc,grid.id,hash,sc.final_seeds(ri));td=apply_topology(raw,tm,spec,grid.id);idx=[cal test];tp=td([cal test]);ev=profile_indices(idx,tp,obs,raw,cache,base,grid,cfg,domain,sc);pm=calibrate_parameter_domain_detector(flatten(ev(1:numel(cal))),sc,selected_eta,hash);thresholds=append(thresholds,threshold_row(grid.id,rep,pm,hash));
            for q=1:numel(test)
                member=ev{numel(cal)+q};for mi=1:numel(sc.diagnostic_methods),j=apply_joint_topology_parameter_decision(td(test(q)),member,pm,sc.diagnostic_methods{mi});j.sample_id=bank(test(q)).sample_id;j.replicate_id=rep;j.grid_id=grid.id;j.optimization_converged=all([member.optimization_converged]);j.experiment_scientific_hash=hash;decisions=append(decisions,j);labels=append(labels,label_row(bank(test(q)),audit,base,grid.id));end
                for k=1:numel(member),profiles=append(profiles,profile_row(bank(test(q)),grid.id,rep,selected_eta,member(k),hash));identrows=append(identrows,ident_row(bank(test(q)),grid.id,rep,member(k),hash));end
            end
        end
        runtimes=append(runtimes,struct('grid_id',grid.id,'sample_count',numel(bank),'candidate_count',7,'parameter_template_count',243,'cache_templates',cache.composite_template_count,'elapsed_s',toc(tall),'experiment_scientific_hash',hash));clear obs raw cache
    end
    metrics=evaluate_stage4a6_metrics(decisions,labels);write_outputs(cfg,sc,bank,decisions,labels,profiles,selection,thresholds,identrows,runtimes,metrics,hash,source_hash,canonical);make_figures(cfg,sc,metrics);out=struct('runtime_s',toc(tall),'metrics',metrics,'selection',selection,'experiment_scientific_hash',hash,'source_tree_hash',source_hash);fprintf('Stage 4A.6 completed in %.3f s\n',out.runtime_s);
end

function obs=make_observations(bank,f,cfg,kind),obs=cell(numel(bank),1);for k=1:numel(bank),[n,c]=topology_apply_parameters(bank(k).truth_network,cfg,bank(k).truth_theta);[m,~]=plc_measurement_bundle(kind,n,bank(k).truth_theta,c);[obs{k},~]=plc_multiview_response(f,n,m,c);end,end
function [cache,audit]=load_a5_cache(cfg,sc,grid,base,theta),a5=stage4a5_1_integrity_config(cfg,'formal');source=stage4a5_1_source_tree_hash(cfg.root_dir);[expected,~]=stage4a5_1_cache_expected(grid,base,theta,cfg,a5,source);path=fullfile(a5.cache_dir,sprintf('stage4a5_1_%s_P0_no_prior.mat',grid.id));if ~exist(path,'file'),error('stage4a6:MissingCache','Run Stage 4A.5.1 formal first.');end;z=load(path,'cache');[ok,reason]=validate_candidate_cache_identity(z.cache,expected);if ~ok,error('stage4a6:InvalidCache','A5.1 cache invalid: %s',reason);end;cache=z.cache;audit=cache.current_equivalence_audit;end
function s=m3_spec(sc,id),specs=stage4a5_method_specs(sc);names=sc.frozen_methods.(id);name=names{4};s=specs(strcmp({specs.method_id},name));end
function td=apply_topology(raw,model,spec,grid),td=struct([]);for i=1:numel(raw),z=apply_stage4a5_confirmation(raw{i},model,spec);z.grid_id=grid;z.scenario_id='P0_no_prior';td=append(td,z);end,end
function ev=profile_indices(indices,td,obs,raw,cache,base,grid,cfg,domain,sc),ev=cell(numel(indices),1);for q=1:numel(indices),i=indices(q);ids_text=td(q).accepted_topology_set;if isempty(ids_text),ids_text=raw{i}.best_equivalence_members;end;ids=strsplit(ids_text,',');members=struct([]);for k=1:numel(ids),g=find(strcmp({base.topology_id},ids{k}),1);ti=find(strcmp(raw{i}.topology_labels,ids{k}),1);ix=raw{i}.topk_evidence.topK_template_indices{ti};starts=[cache.templates(ix(1:min(3,numel(ix)))).theta];e=compute_stage4a6_member_evidence(obs{i},grid.frequency_hz,base(g),cfg,domain,starts,sc.optimization);members=append(members,e);end;ev{q}=members;end,end
function x=flatten(c),x=struct([]);for k=1:numel(c),x=append(x,c{k});end;if isempty(x),error('stage4a6:NoCalibrationEvidence','No accepted calibration member evidence.');end,end
function r=label_row(b,audit,base,grid),[cl,n]=class_for_key(audit,base,b.canonical_key);r=struct('sample_id',b.sample_id,'replicate_id',b.replicate_id,'grid_id',grid,'category',b.category,'outlier_dimension',b.outlier_dimension,'outlier_severity',b.outlier_severity,'parameter_domain_truth',b.parameter_domain_truth,'truth_topology_id',b.truth_topology_id,'truth_is_nonunique',n>1,'truth_equivalence_class',cl);end
function [lab,n]=class_for_key(a,b,key),lab='';n=0;g=find(strcmp({b.canonical_key},key),1);for k=1:numel(a.equivalence_classes),if any(a.equivalence_classes{k}.member_indices==g),lab=a.equivalence_classes{k}.label;n=numel(a.equivalence_classes{k}.member_indices);return;end,end,end
function r=profile_row(b,grid,rep,eta,e,h),r=struct('sample_id',b.sample_id,'replicate_id',rep,'grid_id',grid,'topology_id',e.topology_id,'category',b.category,'outlier_dimension',b.outlier_dimension,'outlier_severity',b.outlier_severity,'eta',eta,'in_distance',e.in_distance,'ext_distance',e.ext_distance,'lambda',e.lambda,'relative_improvement',e.relative_improvement,'extended_outside',e.extended_outside,'boundary_hit',e.boundary_hit,'outward_decrease',e.outward_decrease,'minimum_boundary_distance',e.minimum_boundary_distance,'minimum_sensitivity',e.minimum_sensitivity,'condition_number',e.condition_number,'effective_rank',e.effective_rank,'optimization_converged',e.optimization_converged,'experiment_scientific_hash',h);end
function r=ident_row(b,grid,rep,e,h),r=struct('sample_id',b.sample_id,'replicate_id',rep,'grid_id',grid,'topology_id',e.topology_id,'parameter_names','main_length_scale,branch_length_scale,branch_load_scale,source_impedance_ohm,receiver_impedance_ohm','sensitivity_norms',mat2str(e.sensitivity_norms,8),'singular_values',mat2str(e.singular_values,8),'condition_number',e.condition_number,'effective_rank',e.effective_rank,'low_sensitivity',mat2str(e.low_sensitivity),'experiment_scientific_hash',h);end
function r=threshold_row(grid,rep,m,h),r=struct('grid_id',grid,'replicate_id',rep,'eta',m.eta,'lambda_threshold',m.lambda_threshold,'relative_improvement_threshold',m.relative_improvement_threshold,'sensitivity_floor',m.sensitivity_floor,'calibration_sample_count',m.calibration_sample_count,'calibration_hash',m.calibration_hash,'experiment_scientific_hash',h);end
function r=eta_row(),r=struct('eta',NaN,'grid_id','','parameter_domain_truth','','parameter_status','');end
function y=append(x,z),if isempty(z),y=x;elseif isempty(x),y=z(:);else,y=[x(:);z(:)];end,end
function write_outputs(cfg,sc,b,d,l,p,s,t,i,r,m,h,sh,canon),pre=sc.output_prefix;data=cfg.results_data;write(bank_rows(b),fullfile(data,[pre '_trial_bank.csv']));write(d,fullfile(data,[pre '_joint_decisions.csv']));write(l,fullfile(data,[pre '_scoring_labels.csv']));write(p,fullfile(data,[pre '_parameter_profiles.csv']));write(s,fullfile(data,[pre '_method_selection.csv']));write(t,fullfile(data,[pre '_thresholds.csv']));write(i,fullfile(data,[pre '_identifiability.csv']));write(r,fullfile(data,[pre '_runtime.csv']));write(m,fullfile(data,[pre '_metrics.csv']));manifest=struct('experiment_scientific_hash',h,'source_tree_hash',sh,'canonical_configuration_text',canon,'runtime_environment_hash',stage4a4_scientific_config_hash(struct('matlab',version,'computer',computer)));write(manifest,fullfile(data,[pre '_configuration_manifest.csv']));save(fullfile(data,[pre '_results.mat']),'sc','b','d','l','p','s','t','i','r','m','manifest','-v7.3');end
function x=bank_rows(b),x=repmat(struct('sample_id','','replicate_id','','split','','category','','truth_topology_id','','canonical_key','','outlier_dimension','','outlier_severity','','parameter_domain_truth','','seed',0),numel(b),1);for k=1:numel(b),x(k)=rmfield(b(k),{'truth_network','truth_theta'});end,end
function write(s,p),if ~isempty(s),writetable(struct2table(s(:)),p);end,end
function make_figures(cfg,sc,m),if isempty(m),return;end;for gi=1:numel(sc.grids),grid=sc.grids(gi).id;x=m(strcmp({m.grid_id},grid));meth=unique({x.method_id},'stable');rec=NaN(1,numel(meth));fa=rec;tsa=rec;for k=1:numel(meth),z=x(strcmp({x.method_id},meth{k}));rec(k)=mean([z.parameter_ood_recall],'omitnan');fa(k)=mean([z.parameter_in_domain_false_alarm],'omitnan');tsa(k)=mean([z.topology_set_accuracy],'omitnan');end;h=figure('Visible','off');bar([rec(:),fa(:),tsa(:)]);set(gca,'XTick',1:numel(meth),'XTickLabel',meth,'XTickLabelRotation',30);legend('parameter OOD recall','in-domain false alarm','topology set accuracy','Location','best');title([grid ' Stage 4A.6 joint audit']);saveas(h,fullfile(cfg.results_figures,[sc.output_prefix '_' grid '_joint_metrics.png']));close(h);end,end
